from pathlib import Path
import pandas as pd

def read_production(farm_id):
    fname = f'production_{farm_id}.csv'
    p = Path('/app/dataset') / fname
    # Try semicolon first for certain files
    semicolon_candidates = ['FARM_C', 'FARM_E', 'FARM_AA', 'FARM_AC', 'FARM_AE', 'FARM_AG']
    # also try for others if normal fails? but be selective
    try_order = []
    if farm_id in semicolon_candidates:
        try_order.append('semicolon')
    try_order.append('normal')
    if farm_id not in semicolon_candidates:
        try_order.append('semicolon')  # as fallback
    for mode in try_order:
        for enc in ['utf-8', 'utf-16le', 'utf-16be']:
            try:
                if mode == 'semicolon':
                    df = pd.read_csv(p, sep=';', encoding=enc, skiprows=3, decimal=',', thousands=None, on_bad_lines='skip')
                else:
                    df = pd.read_csv(p, sep=None, engine='python', skiprows=3, encoding=enc, on_bad_lines='skip')
                if len(df.columns) <= 1:
                    continue
                df.columns = [c.strip().replace('\t', '').replace('\ufeff', '') for c in df.columns]
                # rename first col
                if 'timestamp' in str(df.columns[0]).lower():
                    df = df.rename(columns={df.columns[0]: 'timestamp'})
                df['timestamp'] = df['timestamp'].astype(str).str.replace('\t', '').str.strip()
                # normalize column names for duplicates like reading/reading
                cols = df.columns.tolist()
                new_cols = []
                seen = {}
                for c in cols:
                    base = c
                    if base in seen:
                        seen[base] += 1
                        new_cols.append(f"{base}_{seen[base]}")
                    else:
                        seen[base] = 0
                        new_cols.append(base)
                df.columns = new_cols
                return df
            except Exception:
                continue
    raise ValueError(f'Could not read {fname}')
