import pandas as pd
import numpy as np

def parse_numeric(s):
    if s is None:
        return np.nan
    if isinstance(s, (int, float)) and not isinstance(s, bool):
        if pd.isna(s):
            return np.nan
        return float(s)
    s = str(s).strip()
    s_lower = s.lower()
    if s_lower in ('timeout', 'err', 'error', 'na', 'n/a', 'none', 'null', '--', ''):
        return np.nan
    # remove common non-numeric chars except -, ., e, E
    # handle commas as decimal or thousands? try to infer
    # common case: comma as decimal in EU format sometimes
    # but also sometimes as thousands; look for pattern like X.XXX,XXX? unlikely here
    # if both . and , present, and comma comes after dot? no. Or if comma is last or followed by 3 digits in a certain pattern
    # heuristic: if s.count(',') == 1 and s.count('.') == 0: treat as decimal comma
    if s.count(',') == 1 and s.count('.') == 0:
        s = s.replace(',', '.')
    elif s.count(',') > 0 and s.count('.') > 0:
        # if comma appears after dot position-wise, treat comma as thousand sep? e.g. 1.000,50
        # or if dot appears after comma? 1,000.50 - common US
        if s.rfind(',') > s.rfind('.'):
            # European: dot thousands, comma decimal
            s = s.replace('.', '').replace(',', '.')
        else:
            # US: comma thousands, dot decimal
            s = s.replace(',', '')
    elif s.count(',') > 0 and s.count('.') == 0:
        # multiple commas - probably thousands
        s = s.replace(',', '')
    try:
        return float(s)
    except:
        return np.nan
