def to_utc(ts_str, tz_name):
    """Parse timestamp string as local time in tz_name, return UTC datetime."""
    s = str(ts_str).strip()
    # Try common formats
    formats = [
        '%Y-%m-%d %H:%M:%S',
        '%Y-%m-%d %H:%M',
        '%d.%m.%Y %H:%M:%S',
        '%d.%m.%Y %H:%M',
        '%m/%d/%Y %H:%M:%S',
        '%m/%d/%Y %H:%M',
        '%Y/%m/%d %H:%M:%S',
        '%Y/%m/%d %H:%M',
    ]
    dt = None
    for fmt in formats:
        try:
            dt = datetime.strptime(s, fmt)
            break
        except:
            continue
    if dt is None:
        # Try pandas to parse
        try:
            dt = pd.to_datetime(s).to_pydatetime()
        except:
            return None
    # Assume local time as given, attach timezone
    try:
        local_tz = ZoneInfo(tz_name)
        dt_local = dt.replace(tzinfo=local_tz)
        return dt_local.astimezone(ZoneInfo('UTC'))
    except Exception:
        return None
