def convert_energy_to_kwh(value, unit):
    unit_norm = str(unit).strip().lower()
    if unit_norm == 'kwh':
        return float(value)
    if unit_norm == 'mwh':
        return float(value) * 1000.0
    if unit_norm == 'wh':
        return float(value) / 1000.0
    if unit_norm == 'btu':
        # British thermal unit - approximate conversion to kWh varies; but commonly 1 kWh = 3412.14 BTU, so 1 BTU = 0.000293071 kWh
        return float(value) * 0.00029307107
    # default: assume kWh
    return float(value)
