    # try specific strategy
    for enc in ['utf-16le', 'utf-8', 'utf-16be']:
        try:
            if farm_id in semicolon_candidates:
                df = pd.read_csv(p, sep=';', encoding=enc, skiprows=3, decimal=',', on_bad_lines='skip')
            else:
                try:
                    df = pd.read_csv(p, sep=',', encoding=enc, skiprows=3, on_bad_lines='skip')
                except:
                    df = pd.read_csv(p, sep=None, engine='python', skiprows=3, encoding=enc, on_bad_lines='skip')
            if len(df.columns) > 1:
                break
        except Exception:
            continue
    else:
        raise ValueError(f'Could not read {fname}')
    df = df.copy()
    df.columns = [str(c).strip().replace('\t', '').replace('\ufeff', '') for c in df.columns]
    if 'timestamp' in str(df.columns[0]).lower():
        df = df.rename(columns={df.columns[0]: 'timestamp'})
    if 'timestamp' in df.columns:
        df['timestamp'] = df['timestamp'].astype(str).str.replace('\t', '').str.strip()
    # disambiguate duplicate column names
    cols = df.columns.tolist()
    new_cols = []
    seen = {}
    for c in cols:
        if c in seen:
            seen[c] += 1
            new_cols.append(f"{c}_{seen[c]}")
        else:
            seen[c] = 0
            new_cols.append(c)
    df.columns = new_cols
    return df
