def choose_best_value_column(df, specified_name):
    # find all columns that match specified_name (case-insensitive, strip)
    specified = str(specified_name).strip().lower()
    candidates = []
    for c in df.columns:
        c_norm = str(c).strip().lower()
        if c_norm == specified or c_norm.startswith(specified) or specified in c_norm:
            candidates.append(c)
    if not candidates:
        # broader search
        for c in df.columns:
            cl = str(c).strip().lower()
            if any(k in cl for k in ['power_reading', 'value', 'reading', 'output', 'yield', 'generation', 'meter', 'kw', 'mwh', 'wh', 'energy']):
                candidates.append(c)
    if not candidates:
        return None
    # if multiple, pick the one with most reasonable stats
    best = candidates[0]
    best_score = -float('inf')
    for c in candidates:
        try:
            s = df[c].apply(lambda x: float(str(x).replace(',', '.')) if isinstance(x, str) else float(x))
            s = s.replace([float('inf'), float('-inf')], float('nan')).dropna()
            if len(s) == 0:
                score = 0
            else:
                # prefer lower coefficient of variation, reasonable max
                mean = s.mean()
                std = s.std()
                cv = std / abs(mean) if mean != 0 else float('inf')
                maxv = s.max()
                # penalize extremely large constant-like or absurd values
                score = -cv - maxv / 1e7 if maxv > 1e6 else -cv
            if score > best_score:
                best = c
                best_score = score
        except:
            continue
    return best
