def to_utc(ts_str, tz_name):
    s = str(ts_str).strip()
    formats = [
        '%Y-%m-%d %H:%M:%S',
        '%Y-%m-%d %H:%M',
        '%d.%m.%Y %H:%M:%S',
        '%d.%m.%Y %H:%M',
        '%m/%d/%Y %H:%M:%S',
        '%m/%d/%Y %H:%M',
        '%Y/%m/%d %H:%M:%S',
        '%Y/%m/%d %H:%M',
    ]
    dt = None
    for fmt in formats:
        try:
            dt = datetime.strptime(s, fmt)
            break
        except:
            continue
    if dt is None:
        try:
            dt = pd.to_datetime(s).to_pydatetime()
        except:
            return None
    try:
        local_tz = ZoneInfo(tz_name)
        dt_local = dt.replace(tzinfo=local_tz)
        return dt_local.astimezone(ZoneInfo('UTC'))
    except Exception:
        return None
