import pandas as pd
import numpy as np

def parse_numeric(s):
    if s is None:
        return np.nan
    if isinstance(s, (int, float)) and not isinstance(s, bool):
        if pd.isna(s):
            return np.nan
        return float(s)
    s = str(s).strip()
    s_lower = s.lower()
    if s_lower in ('timeout', 'err', 'error', 'na', 'n/a', 'none', 'null', '--', ''):
        return np.nan
    if s.count(',') == 1 and s.count('.') == 0:
        s = s.replace(',', '.')
    elif s.count(',') > 0 and s.count('.') > 0:
        if s.rfind(',') > s.rfind('.'):
            s = s.replace('.', '').replace(',', '.')
        else:
            s = s.replace(',', '')
    elif s.count(',') > 0 and s.count('.') == 0:
        s = s.replace(',', '')
    try:
        return float(s)
    except:
        return np.nan
